import json
from pathlib import Path

def encode(rows):
    return json.dumps(rows)

def decode(text):
    rows = json.loads(text)
    if not isinstance(rows, list):
        raise ValueError("unsupported store format")
    return rows

def write(path, rows):
    Path(path).write_text(encode(rows))
